package android.view;
import java.util.ArrayList;
import android.content.Context;
import android.content.Intent;
import android.content.res.ColorStateList;
import android.graphics.PorterDuff;
import android.graphics.drawable.Drawable;
public class SimpleMenu implements Menu {
    protected final Context context; protected final ArrayList<MenuItem> items=new ArrayList<MenuItem>();
    public SimpleMenu(Context context) { this.context=context; }
    public MenuItem add(CharSequence title) { return add(0,0,items.size(),title); }
    public MenuItem add(int group,int id,int order,CharSequence title) { Item item=new Item(group,id,order,title); int i=0; while(i<items.size() && items.get(i).getOrder()<=order) i++; items.add(i,item); return item; }
    public SubMenu addSubMenu(int group,int id,int order,CharSequence title) { Item item=(Item)add(group,id,order,title); item.sub=new Sub(item); return item.sub; }
    public MenuItem findItem(int id) { for(MenuItem i:items) { if(i.getItemId()==id)return i; if(i.hasSubMenu()) { MenuItem n=i.getSubMenu().findItem(id); if(n!=null)return n; } } return null; }
    public MenuItem getItem(int index) { return items.get(index); } public void removeItem(int id) { for(int i=0;i<items.size();i++) if(items.get(i).getItemId()==id) { items.remove(i); return; } } public void setQwertyMode(boolean q) {} public int size() { return items.size(); } public void clear() { items.clear(); }
    private class Item implements MenuItem {
        final int group,id,order; CharSequence title,condensed,description,tooltip; boolean visible=true,enabled=true,checkable,checked,expanded; Drawable icon; ColorStateList tint; PorterDuff.Mode mode; Intent intent; char alpha,numeric; int alphaMods=4096,numericMods=4096; View actionView; OnActionExpandListener expandListener; OnMenuItemClickListener clickListener; Sub sub;
        Item(int g,int i,int o,CharSequence t) { group=g;id=i;order=o;title=t; }
        public int getItemId(){return id;} public int getGroupId(){return group;} public int getOrder(){return order;} public CharSequence getTitle(){return title;} public CharSequence getTitleCondensed(){return condensed==null?title:condensed;}
        public MenuItem setTitle(CharSequence t){title=t;return this;} public MenuItem setTitle(int id){return setTitle(context.getText(id));} public MenuItem setTitleCondensed(CharSequence t){condensed=t;return this;}
        public MenuItem setVisible(boolean b){visible=b;return this;} public boolean isVisible(){return visible;} public MenuItem setEnabled(boolean b){enabled=b;return this;} public boolean isEnabled(){return enabled;} public MenuItem setCheckable(boolean b){checkable=b;return this;} public boolean isCheckable(){return checkable;} public MenuItem setChecked(boolean b){checked=b;return this;} public boolean isChecked(){return checked;}
        public MenuItem setIcon(int i){icon=context.getResources().getDrawable(i);return this;} public MenuItem setIcon(Drawable d){icon=d;return this;} public Drawable getIcon(){return icon;} public MenuItem setIconTintList(ColorStateList t){tint=t;return this;} public ColorStateList getIconTintList(){return tint;} public MenuItem setIconTintMode(PorterDuff.Mode m){mode=m;return this;} public PorterDuff.Mode getIconTintMode(){return mode;}
        public MenuItem setIntent(Intent i){intent=i;return this;} public Intent getIntent(){return intent;} public MenuItem setAlphabeticShortcut(char c){alpha=c;return this;} public MenuItem setAlphabeticShortcut(char c,int m){alpha=c;alphaMods=m;return this;} public char getAlphabeticShortcut(){return alpha;} public int getAlphabeticModifiers(){return alphaMods;} public MenuItem setNumericShortcut(char c){numeric=c;return this;} public MenuItem setNumericShortcut(char c,int m){numeric=c;numericMods=m;return this;} public char getNumericShortcut(){return numeric;} public int getNumericModifiers(){return numericMods;} public MenuItem setShortcut(char n,char a){numeric=n;alpha=a;return this;} public MenuItem setShortcut(char n,char a,int nm,int am){numeric=n;alpha=a;numericMods=nm;alphaMods=am;return this;}
        public MenuItem setContentDescription(CharSequence c){description=c;return this;} public CharSequence getContentDescription(){return description;} public MenuItem setTooltipText(CharSequence t){tooltip=t;return this;} public CharSequence getTooltipText(){return tooltip;}
        public MenuItem setActionView(View v){actionView=v;return this;} public MenuItem setActionView(int id){return this;} public View getActionView(){return actionView;} public boolean expandActionView(){if(actionView==null || expandListener!=null&&!expandListener.onMenuItemActionExpand(this))return false;expanded=true;return true;} public boolean collapseActionView(){if(!expanded || expandListener!=null&&!expandListener.onMenuItemActionCollapse(this))return false;expanded=false;return true;} public boolean isActionViewExpanded(){return expanded;} public MenuItem setOnActionExpandListener(OnActionExpandListener l){expandListener=l;return this;} public MenuItem setOnMenuItemClickListener(OnMenuItemClickListener l){clickListener=l;return this;}
        public void setShowAsAction(int a){} public MenuItem setShowAsActionFlags(int a){return this;} public boolean hasSubMenu(){return sub!=null;} public SubMenu getSubMenu(){return sub;} public ContextMenu.ContextMenuInfo getMenuInfo(){return null;}
    }
    private class Sub extends SimpleMenu implements SubMenu { final Item item; Sub(Item i){super(SimpleMenu.this.context);item=i;} public void clearHeader(){} public SubMenu setHeaderTitle(CharSequence t){return this;} public SubMenu setHeaderTitle(int i){return this;} public SubMenu setHeaderIcon(Drawable d){return this;} public SubMenu setHeaderIcon(int i){return this;} public SubMenu setHeaderView(View v){return this;} public SubMenu setIcon(Drawable d){item.setIcon(d);return this;} public SubMenu setIcon(int i){item.setIcon(i);return this;} public MenuItem getItem(){return item;} }
}
